insert into tb_file_item (
	  REF_SEQ_NO
	, BIZ_TYPE
	, FILE_PATH
	, FILE_NAME
	, file_save_name
	, file_size
	, file_fancy_size
	, file_down_cnt
	, reg_date
	, reg_user
	, upd_date
	, upd_user
	, thum_save_name
) values (			
	  #{refSeqNo}
	, #{bizType}
	, #{filePath}
	, #{fileName}
	, #{fileSaveName}
	, #{fileSize}
	, #{fileFancySize}
	, #{fileDownCnt}
	, now()
	, #{regUser}
	, now()
	, #{updUser}
	, #{thumSaveName}
)
